export const partOneRules={"family": [{"title": "Читаем букву a · с. 29", "text": "Name и cake: [eɪ]. Bag и flag: [æ]. Слушай и повторяй слова; затем проверь себя в заданиях.", "en": "name, cake, bag, flag", "ru": "имя, торт, сумка, флаг"}, {"title": "Me, him, her, us, them · с. 36", "text": "После действия или предлога нужны объектные местоимения: I → me; he → him; she → her; we → us; they → them. You и it сохраняют форму.", "en": "Look at me. Play with her. Follow us.", "ru": "Посмотри на меня. Поиграй с ней. Следуй за нами."}], "food": [{"title": "Говорим о количестве · с. 47", "text": "A lot of — много. Not much с неисчисляемыми словами (milk, chocolate); not many с исчисляемыми во множественном числе (apples, biscuits).", "en": "I eat a lot of fruit. I do not eat much chocolate. I do not eat many biscuits.", "ru": "Я ем много фруктов. Я ем мало шоколада и печенья."}], "weekend": [{"title": "Правописание и произношение -ed · с. 97", "text": "После согласной + y: study → studied. После гласной + y: play → played. Stop → stopped; британский вариант travel → travelled. Окончание звучит [t] в washed, [d] в played, [ɪd] в visited.", "en": "washed, played, visited, studied, stopped, travelled", "ru": "мыл, играл, посещал, учился, остановился, путешествовал"}]};
